        r.add("pawday.outbox.workers-enabled",()->false);r.add("pawday.outbox.consumer-enabled",()->false);r.add("pawday.search.consumers-enabled",()->false);r.add("pawday.search.workers-enabled",()->false);r.add("pawday.storage.cleanup-enabled",()->false);
